class LmdbGraphPatternImplicationTest {

	@TempDir
	File dataDir;

	static Stream<Arguments> graphPatternConfigurations() {
		return Stream.of(
			"GRAPH ?g { ?s <urn:p> ?o }",
			"GRAPH <urn:g> { ?s <urn:p> ?o }",
			"{ GRAPH ?g { ?s <urn:p> ?o } } OPTIONAL { ?s <urn:q> ?optional }",
			"{ GRAPH ?g { ?s <urn:p> ?o } } MINUS { ?s <urn:q> ?excluded }",
			"{ SELECT ?s ?o { GRAPH ?g { ?s <urn:p> ?o } } }",
			"{ GRAPH ?g { ?s <urn:p> ?o } } UNION { GRAPH ?g { ?s <urn:p> ?o } }"
		).flatMap(required -> Stream.of(false, true).map(experimental -> Arguments.of(required, experimental)));
	}

	@ParameterizedTest
	@MethodSource("graphPatternConfigurations")
	void namedGraphDoesNotImplyDefaultGraphExists(String required, boolean experimental) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(experimental);
		config.setExperimentalQueryOptimizations(experimental);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			connection.add(vf.createIRI("urn:s"), vf.createIRI("urn:p"), vf.createIRI("urn:o"), vf.createIRI("urn:g"));
			connection.add(vf.createIRI("urn:noise"), vf.createIRI("urn:q"), vf.createIRI("urn:o"),
					vf.createIRI("urn:d"));
			if (experimental) {
				assertTrue(store.awaitSketchesReady(60, TimeUnit.SECONDS));
			}
			String prefix = "SELECT * FROM <urn:d> FROM NAMED <urn:g> WHERE { " + required;
			try (var rows = connection.prepareTupleQuery(prefix + " FILTER EXISTS { ?s <urn:p> ?o } }").evaluate()) {
				assertFalse(rows.hasNext(), "Named graph rows cannot prove a default graph probe");
			}
			var negative = connection.prepareTupleQuery(prefix + " FILTER NOT EXISTS { ?s <urn:p> ?o } }");
			try (var rows = negative.evaluate()) {
				assertTrue(rows.hasNext(), () -> negative.explain(Explanation.Level.Optimized).toString());
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void requiredPatternProofRespectsGraphAndBindingBoundaries() {
		StatementPattern expected = pattern();
		assertFalse(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(new Graph(Var.of("g"), pattern()), expected));
		assertFalse(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(
				new Projection(pattern(), new ProjectionElemList(new ProjectionElem("o", "s"))), expected));
		assertFalse(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(new Extension(pattern(),
				new ExtensionElem(new ValueConstant(SimpleValueFactory.getInstance().createIRI("urn:other")), "s")),
				expected));
		StatementPattern named = pattern(StatementPattern.Scope.NAMED_CONTEXTS);
		assertFalse(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(named, expected));
		assertFalse(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(new LeftJoin(new SingletonSet(), pattern()),
				expected));
		assertFalse(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(new Difference(new SingletonSet(), pattern()),
				expected));
		assertTrue(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(new Join(new SingletonSet(), pattern()),
				expected));
		assertTrue(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(new LeftJoin(pattern(), new SingletonSet()),
				expected));
		assertTrue(LmdbJoinPlanSupport.containsEquivalentRequiredPattern(new Difference(pattern(), new SingletonSet()),
				expected));
	}

	private static StatementPattern pattern() {
		return pattern(StatementPattern.Scope.DEFAULT_CONTEXTS);
	}

	private static StatementPattern pattern(StatementPattern.Scope scope) {
		return new StatementPattern(scope, Var.of("s"),
				Var.of("p", SimpleValueFactory.getInstance().createIRI("urn:p")), Var.of("o"));
	}
}
